{"chunk_id":"ccce5c","wall_time_seconds":0.000008758,"exit_code":0,"original_token_count":3234,"output":"#!/usr/bin/env python3
"""Evaluate registered CT comparisons from completed cases; never select a reference."""
from pathlib import Path
from datetime import datetime, timezone
import argparse
import hashlib
import json
import numpy as np
from postprocess import own_case, observer_case, relative_comparison, exposure_comparison, stats, tsv, ORIGIN
from run_records import completed_output

ROOT=Path(__file__).resolve().parents[1]
FIELDS=('n','v','f_incident')


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--case-root',type=Path,default=ROOT/'results')
    parser.add_argument('--output',type=Path,default=ROOT/'validation/ct_convergence_summary.json')
    args=parser.parse_args()
    plan_path=ROOT/'validation/ct_convergence_plan.json'
    plan=json.loads(plan_path.read_text())
    gti=tsv(ROOT/'observations/xmm_gtis.tsv');gti=gti[gti['detector']=='pn']
    spans=list(zip(gti['start_mjd_utc']-ORIGIN,gti['stop_mjd_utc']-ORIGIN))
    frames={str(f):list(zip(gti[gti['frame']==f]['start_mjd_utc']-ORIGIN,gti[gti['frame']==f]['stop_mjd_utc']-ORIGIN)) for f in np.unique(gti['frame'])}
    cases={};sources={};excluded={};configs={}
    for folder in sorted(args.case_root.resolve().glob('ct*')):
        if not folder.is_dir():continue
        if not completed_output(folder):
            excluded[folder.name]='No completed statistics/probes or explicit incomplete controller marker'
            continue
        config=dict(line.split('=',1) for line in (folder/'run.cfg').read_text().splitlines() if '=' in line)
        trace=np.genfromtxt(folder/'ct_trace.csv',delimiter=',',names=True,ndmin=1)
        if len(trace)<2 or abs(trace['day'][0]-float(config['start_day']))>1e-10 or abs(trace['day'][-1]-float(config['end_day']))>1e-10 or np.any(np.diff(trace['day'])<=0):
            excluded[folder.name]='Native trace lacks monotonic configured endpoints'
            continue
        cases[folder.name]=observer_case(own_case(folder.name,folder),{'time_convention':'observer_arrival'})
        configs[folder.name]=config
        sources[folder.name]={name:sha(folder/name) for name in ['probe.csv','run.cfg','statistics.json','ct_trace.csv','candidate_status.json'] if (folder/name).exists()}

    campaign_path=ROOT/'validation/ct_campaign_summary.json'
    campaign=json.loads(campaign_path.read_text()) if campaign_path.exists() else {}
    checked_files={}
    def matches(path,expected):
        path=Path(path)
        if path not in checked_files:
            checked_files[path]=sha(path) if path.is_file() else None
        return checked_files[path]==expected
    qualification={}
    for name in cases:
        record=campaign.get('cases',{}).get(name,{})
        reasons=[]
        if campaign.get('registered_plan_sha256')!=sha(plan_path):
            reasons.append('Campaign audit is missing or uses another registered plan')
        if campaign.get('script_sha256')!=sha(ROOT/'scripts/audit_ct_campaign.py'):
            reasons.append('Campaign audit helper hash is missing or stale')
        if record.get('path')!=str((args.case_root/name).resolve()):
            reasons.append('Campaign case path is missing or different')
        hashes=record.get('completion_evidence_sha256',{})
        if not hashes or not all(matches(p,h) for p,h in hashes.items()):
            reasons.append('Campaign completion evidence is missing or stale')
        for key in ['native_fields_cache','observer_arrival_cache']:
            receipt=record.get(key,{})
            p=Path(receipt.get('file','/nonexistent'))
            cache=json.loads(p.read_text()) if p.is_file() else {}
            inputs=cache.get('inputs_sha256',{})
            if cache.get('signature')!=receipt.get('signature') or not inputs or not all(matches(p,h) for p,h in inputs.items()):
                reasons.append(key+' is missing or has stale inputs')
        provenance=args.case_root/name/'input_code_provenance.json'
        pins=json.loads(provenance.read_text()) if provenance.is_file() else {}
        if not pins or not all(matches(ROOT/p,h) for p,h in pins.items()):
            reasons.append('Runtime source/input hash receipt is missing or mismatched')
        formulation=record.get('formulation',{})
        if formulation.get('all_applicable_formulation_gates_passed') is not True:
            reasons.append('Applicable formulation gates are missing or failed')
        entropy=formulation.get('thermal',{}).get('physical_entropy_bound',{})
        if not configs[name].get('cme_boundary_csv') and entropy.get('passed') is not True:
            reasons.append('Applicable physical entropy-bound diagnostic is missing or failed')
        qualification[name]=dict(passed=not reasons,reasons=reasons)

    def compare(left,right,targets=None,observables=False):
        result=dict(left=left,right=right,targets=targets,passed=None)
        if left not in cases or right not in cases:
            return dict(result,availability='missing',missing_cases=[n for n in (left,right) if n not in cases])
        a,b=cases[left],cases[right]
        comparison=relative_comparison(a,b)
        am,bm=stats(a,spans),stats(b,spans)
        result.update(availability='complete',comparison=comparison,
                      PN_GTI_mean_relative_change={k:am[k]/bm[k]-1 for k in FIELDS})
        if targets:
            result['passed']=all(comparison[k]['maximum_relative_difference']<=v for k,v in targets.items())
        if observables:
            metrics=exposure_comparison(a,b,spans,frames)
            registration=plan['exposure_observable_metrics']
            mapping={'PN_GTI_mean_relative_change':'PN_GTI_mean_relative_targets',
                     'maximum_absolute_frame_GTI_mean_relative_change':'maximum_individual_PN_frame_GTI_mean_relative_targets',
                     'PN_GTI_integrated_absolute_curve_difference_over_fine_integral':'PN_GTI_time_integrated_absolute_curve_difference_over_fine_curve_integral_targets'}
            outcomes={key:all(abs(metrics[key][k])<=v for k,v in registration[target].items()) for key,target in mapping.items()}
            result['exposure_observables']=dict(comparison=metrics,passed_each=outcomes,passed=all(outcomes.values()),does_not_replace_original_pointwise_targets=True)
        return result

    width_targets=plan['domain_first']['eligible_narrow_domain_maximum_published_pointwise_relative_changes']
    domain=[compare(f'ct96_w{w}','ct96_w60',width_targets) for w in (30,45)]
    for check in domain:
        check['formulation_and_provenance_qualified']=all(qualification.get(n,{}).get('passed') is True for n in (check['left'],check['right']))
        reasons=[]
        if check['availability']=='complete':
            a,b=(configs[n] for n in (check['left'],check['right']))
            for name,cfg in [(check['left'],a),(check['right'],b)]:
                expected=plan['domain_first']['cases'][name]
                if any(float(cfg[k])!=v for k,v in zip(['nr','ntheta','nphi','latmax_deg'],expected)):
                    reasons.append(name+' does not have its registered domain grid')
                for key,value in [('cfl',plan['temporal_control']['CFL'][0]),('start_day',plan['initial_condition_control']['baseline_start_day']),('rmax_au',2.3)]:
                    if float(cfg[key])!=value:reasons.append(name+' has an unregistered '+key)
            ignored={'ntheta','latmax_deg','output_dir','threads','ct_radial_blocks','output_start_day','snapshot_days','ecliptic_slice_pixels','ecliptic_extent_au','ecliptic_to_solar_matrix_csv','ecliptic_to_solar_matrix'}
            for key in set(a)|set(b):
                if key in ignored:continue
                av,bv=a.get(key),b.get(key)
                if key in ('boundary_map_csv','probes_csv'):
                    same=av is not None and bv is not None and sha(Path(av))==sha(Path(bv))
                else:
                    try:same=float(av)==float(bv)
                    except (TypeError,ValueError):same=av==bv
                if not same:reasons.append('Domain pair differs in '+key)
            for field in ['r_au.npy','r_faces_au.npy','phi_rad.npy','phi_faces_rad.npy']:
                if not np.array_equal(np.load(args.case_root/check['left']/field),np.load(args.case_root/check['right']/field)):
                    reasons.append('Domain pair does not share identical '+field)
            for name,cfg in [(check['left'],a),(check['right'],b)]:
                tf=np.load(args.case_root/name/'theta_faces_rad.npy')
                step=np.deg2rad(plan['domain_first']['angular_spacing_deg'])
                if not np.allclose(np.diff(tf),step,rtol=0,atol=1e-13):
                    reasons.append(name+' has a different physical theta spacing')
                auxiliary=np.pi/step
                if abs((np.pi/2-np.deg2rad(float(cfg['latmax_deg'])))/step-round((np.pi/2-np.deg2rad(float(cfg['latmax_deg'])))/step))>1e-10 or abs(auxiliary-round(auxiliary))>1e-10:
                    reasons.append(name+' does not align with the full-sphere surface driver')
        else:reasons.append('Both registered domain cases must complete')
        check['experiment_identity']=dict(passed=not reasons,reasons=reasons)
    eligible=next((w for w,c in zip((30,45),domain) if c['passed'] is True and c['formulation_and_provenance_qualified'] and c['experiment_identity']['passed']),None)
    time_targets={k:plan['temporal_control']['maximum_pointwise_n_v_incident_flux_relative_change'] for k in FIELDS}
    initial_targets={k:plan['initial_condition_control']['maximum_pointwise_n_v_incident_flux_relative_target'] for k in FIELDS}
    outer_targets={k:plan['outer_extent_control']['maximum_pointwise_n_v_incident_flux_relative_target'] for k in FIELDS}
    spatial_pairs=[('ct96_w30','ct96_w30_phi144'),('ct96_w30_phi144','ct96_w30_phi192'),
                   ('ct96_w30_phi192','ct96_w30_theta32_phi192'),('ct96_w30_theta32_phi192','ct128_w30_theta32_phi192')]
    physics=['cooler','hotter','density_low','density_high','slow','fast','gamma53','Bzero','frozenBr26','cme12','cme24']
    result=dict(author='Codex-root',created_utc=datetime.now(timezone.utc).isoformat(),
                time_convention='observer_arrival',case_root=str(args.case_root.resolve()),
                decision='Comparison audit only; no reference selection or uncertainty interval is inferred.',
                plan_sha256=sha(plan_path),case_source_sha256=sources,case_qualification=qualification,excluded_cases=excluded,
                domain=dict(comparisons=domain,eligible_narrow_domain=eligible,widest_reference='ct96_w60',
                            eligibility_interpretation='First narrower domain that passes against completed60deg; null requires60deg or completion of missing comparisons.'),
                temporal=dict(comparisons=[compare('ct96_w30_half','ct96_w30',time_targets)]),
                initial_condition=dict(comparisons=[compare('ct96_w30_start6','ct96_w30',initial_targets)]),
                outer_extent=dict(comparisons=[compare(*plan['outer_extent_control'].get('comparison_pair',['ct96_w30_outer','ct96_w30']),outer_targets)],
                                  original_failed_attempt=plan['outer_extent_control'].get('original_attempt')),
                spatial=dict(comparisons=[compare(a,b,plan['conditional_coordinate_refinement']['maximum_pointwise_relative_targets'],True) for a,b in spatial_pairs],
                             qualification='These coordinate comparisons apply to30deg only if domain eligibility passes; missing/failed tests remain explicit.'),
                physics=dict(comparisons=[compare('ct96_w30_'+label,'ct96_w30') for label in physics]+[compare('ct96_w30_cme12','ct96_w30_cme24')],
                             interpretation='Conditional physical/input sensitivities, with no pass flag and no confidence-interval interpretation.'),
                input_sha256={str(p.relative_to(ROOT)):sha(p) for p in [Path(__file__),ROOT/'scripts/postprocess.py',ROOT/'scripts/observer_clock.py',ROOT/'scripts/run_records.py',ROOT/'observations/light_travel_time_audit.py',ROOT/'observations/xmm_gtis.tsv',ROOT/'observations/ephemeris_comet.tsv',ROOT/'observations/ephemeris_wind.tsv',ROOT/'observations/coordinate_system.json']+([campaign_path] if campaign_path.exists() else [])})
    args.output.parent.mkdir(parents=True,exist_ok=True)
    args.output.write_text(json.dumps(result,indent=2,allow_nan=False)+'\n')
    print(json.dumps(dict(output=str(args.output),completed_cases=list(cases),eligible_narrow_domain=eligible,
                          checks={key:[dict(left=c['left'],right=c['right'],availability=c['availability'],passed=c['passed']) for c in result[key]['comparisons']] for key in ['domain','temporal','initial_condition','outer_extent','spatial']}),indent=2))


if __name__=='__main__':main()
"}

